export function WeatherStrip({
  weather,
  cities = [],
  onSearch,
  onCityChange,
  onUseMyLocation,
  locating = false,
  geoError = null,
}: {
  weather: WeatherPayload;
  cities?: City[];
  onSearch?: (q: string) => void;
  onCityChange?: (c: City) => void;
  onUseMyLocation?: () => void;
  locating?: boolean;
